#include "oracis/memory/guest_memory.hpp"
#include "oracis/memory/guest_memory_abi.h"
#include "oracis/memory/nds_game_card_control.hpp"
#include "oracis/memory/nds_interrupt_control.hpp"
#include "oracis/recomp/runtime_arm.h"
#include <array>
#include <cstdint>
#include <cstdio>
namespace {
int fail(const char*m){std::fprintf(stderr,"nds_game_card_control_test: %s\n",m);return 1;}
void write_b7(uint32_t off){using oracis::memory::NdsGameCardControl;const uint8_t b[8]={0xB7u,uint8_t(off>>24u),uint8_t(off>>16u),uint8_t(off>>8u),uint8_t(off),0u,0u,0u};for(uint32_t i=0;i<8u;++i)bus_write_u8(NdsGameCardControl::CommandAddress+i,b[i]);}
}
int main(){using namespace oracis::memory;GuestMemory memory;NdsInterruptControl irq(memory);NdsGameCardControl card(irq);if(card.install()!=Status::Ok)return fail("install failed");std::array<uint8_t,0x400> image{};for(uint32_t i=0;i<image.size();++i)image[i]=uint8_t((i*13u+7u)&255u);if(card.mount_image(image.data(),uint32_t(image.size()))!=Status::Ok)return fail("mount failed");ArmCpuState a9{},a7{};a9.cpsr=ORACIS_ARM_MODE_SYSTEM;a7.cpsr=ORACIS_ARM_MODE_SYSTEM;if(!oracis_arm_runtime_bind_cpus(&a9,&a7)||!oracis_bus_bind_memory(&memory)||!oracis_bus_bind_interrupt_control(&irq)||!oracis_bus_bind_game_card_control(&card))return fail("bus bind failed");if(oracis_bus_bind_game_card_control(&card)||oracis_bus_unbind_interrupt_control(&irq)||oracis_bus_unbind_memory(&memory))return fail("dependency guard failed");constexpr uint32_t imask=NdsGameCardControl::GameCardTransferIrqMask;bus_write_u16(NdsGameCardControl::AuxSpiControlAddress,uint16_t(NdsGameCardControl::AuxSpiIrqEnableMask));auto word=[&](uint32_t o){return uint32_t(image[o])|(uint32_t(image[o+1u])<<8u)|(uint32_t(image[o+2u])<<16u)|(uint32_t(image[o+3u])<<24u);};
write_b7(0x20u);const uint32_t small=NdsGameCardControl::RomCtrlResetReleaseMask|(7u<<NdsGameCardControl::RomCtrlBlockSizeShift);if(card.write(NDS_ARM9,NdsGameCardControl::RomControlAddress,4u,small|NdsGameCardControl::RomCtrlStartBusyMask)!=Status::Ok||!card.busy())return fail("B7 transaction failed to start");if(bus_read_u32(NdsGameCardControl::RomControlAddress)&NdsGameCardControl::RomCtrlDrqMask)return fail("early DRQ");card.advance_bus_cycles(39u);if(bus_read_u32(NdsGameCardControl::RomControlAddress)&NdsGameCardControl::RomCtrlDrqMask)return fail("first word latency wrong");card.advance_bus_cycles(1u);if(!(bus_read_u32(NdsGameCardControl::RomControlAddress)&NdsGameCardControl::RomCtrlDrqMask))return fail("DRQ not set");if(bus_read_u32(NdsGameCardControl::DataAddress)!=word(0x20u)||card.busy()||((bus_read_u32(NdsGameCardControl::RomControlAddress)&(NdsGameCardControl::RomCtrlStartBusyMask|NdsGameCardControl::RomCtrlDrqMask))!=0u)||!(bus_read_u32(NdsInterruptControl::IfAddress)&imask))return fail("one-word read or completion IRQ failed");
if(irq.write(NDS_ARM9,NdsInterruptControl::IfAddress,4u,imask)!=Status::Ok)return fail("clear irq failed");write_b7(0x100u);const uint32_t normal=NdsGameCardControl::RomCtrlResetReleaseMask|(1u<<NdsGameCardControl::RomCtrlBlockSizeShift);if(card.write(NDS_ARM9,NdsGameCardControl::RomControlAddress,4u,normal|NdsGameCardControl::RomCtrlStartBusyMask)!=Status::Ok)return fail("block read start failed");card.advance_bus_cycles(40u);for(uint32_t n=0;n<128u;++n){if(n&&!(bus_read_u32(NdsGameCardControl::RomControlAddress)&NdsGameCardControl::RomCtrlDrqMask))return fail("DRQ not ready for word");if(bus_read_u32(NdsGameCardControl::DataAddress)!=word(0x100u+n*4u))return fail("block word mismatch");if(n<127u)card.advance_bus_cycles(20u);}if(card.busy()||!(bus_read_u32(NdsInterruptControl::IfAddress)&imask))return fail("128 word transfer incomplete");if(irq.write(NDS_ARM9,NdsInterruptControl::IfAddress,4u,imask)!=Status::Ok)return fail("second irq clear failed");write_b7(0x400u);if(card.write(NDS_ARM9,NdsGameCardControl::RomControlAddress,4u,normal|NdsGameCardControl::RomCtrlStartBusyMask)!=Status::AddressOverflow||card.busy())return fail("range check not transactional");write_b7(0u);if(card.write(NDS_ARM9,NdsGameCardControl::RomControlAddress,4u,normal|NdsGameCardControl::RomCtrlKey2DataMask|NdsGameCardControl::RomCtrlStartBusyMask)!=Status::PermissionDenied)return fail("KEY2 accepted unexpectedly");if(!oracis_bus_unbind_game_card_control(&card)||!oracis_bus_unbind_interrupt_control(&irq)||!oracis_bus_unbind_memory(&memory)||!oracis_arm_runtime_unbind_cpus(&a9,&a7))return fail("bus teardown failed");std::puts("NDS Game Card raw B7 reads, DRQ timing, blocks and completion IRQ passed");return 0;}
